// AI-powered ticket categorization
const message = $input.item.json.message.toLowerCase();
const subject = $input.item.json.subject.toLowerCase();

let category = 'general';
let priority = 'normal';

// Categorize based on keywords
if (message.includes('bug') || message.includes('error') || message.includes('broken')) {
  category = 'technical';
  priority = 'high';
} else if (message.includes('payment') || message.includes('billing') || message.includes('subscription')) {
  category = 'billing';
  priority = 'high';
} else if (message.includes('how to') || message.includes('tutorial') || message.includes('help with')) {
  category = 'how_to';
  priority = 'normal';
} else if (message.includes('feature request') || message.includes('suggestion')) {
  category = 'feature_request';
  priority = 'low';
} else if (message.includes('refund') || message.includes('cancel')) {
  category = 'billing';
  priority = 'urgent';
}

return { json: { ...$input.item.json, category, priority } };

// Check knowledge base for known issues
const category = $input.item.json.category;
const message = $input.item.json.message.toLowerCase();

const knowledgeBase = {
  'password reset': {
    solution: 'Visit https://rohimayapublishing.com/reset-password and follow the instructions.',
    autoRespond: true
  },
  'api key': {
    solution: 'Your API keys can be found in Settings > API Keys. Make sure to keep them secure.',
    autoRespond: true
  },
  'export issue': {
    solution: 'Try clearing your browser cache and try again. If the issue persists, please let us know.',
    autoRespond: true
  },
  'subscription cancel': {
    solution: 'You can cancel your subscription anytime in Settings > Billing. Your access will continue until the end of your billing period.',
    autoRespond: true
  },
  'file upload': {
    solution: 'Make sure your file is under 10MB and in a supported format (.txt, .docx, .md). Try refreshing the page.',
    autoRespond: true
  }
};

let solution = null;
let autoRespond = false;

for (const [keyword, data] of Object.entries(knowledgeBase)) {
  if (message.includes(keyword)) {
    solution = data.solution;
    autoRespond = data.autoRespond;
    break;
  }
}

return { json: { ...$input.item.json, solution, autoRespond } };

